			, t.[ExternalData]
			, t.[ExternalValue]
			, t.[CreatedDate]
		FROM [dbo].[Customer] AS t
		LEFT JOIN [dbo].[OrganizationUnit] AS j1 ON j1.[Id] = t.[BranchId]
		LEFT JOIN [dbo].[OrganizationUnit] AS j2 ON j2.[Id] = t.[DepartmentId]
		LEFT JOIN [dbo].[Company] AS j3 ON j3.[Id] = t.[CompanyId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[DisplayName] LIKE CONCAT('%', @SearchText, '%') OR t.[PhoneNumber] LIKE CONCAT('%', @SearchText, '%') OR t.[TaxCode] LIKE CONCAT('%', @SearchText, '%') OR t.[FirstName] LIKE CONCAT('%', @SearchText, '%') OR t.[LastName] LIKE CONCAT('%', @SearchText, '%') OR t.[IdentityNumber] LIKE CONCAT('%', @SearchText, '%') OR t.[LegalName] LIKE CONCAT('%', @SearchText, '%') OR t.[BusinessRegistrationNumber] LIKE CONCAT('%', @SearchText, '%') OR t.[LegalRepresentativeName] LIKE CONCAT('%', @SearchText, '%') OR t.[ContactPersonName] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@CustomerType, '') = '' OR t.[CustomerType] = @CustomerType)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@RegionId IS NULL OR t.[RegionId] = @RegionId)
			AND (@AreaId IS NULL OR t.[AreaId] = @AreaId)
			AND (@BranchId IS NULL OR t.[BranchId] = @BranchId)
			AND (@DepartmentId IS NULL OR t.[DepartmentId] = @DepartmentId)
			AND (@UserAssignId IS NULL OR t.[UserAssignId] = @UserAssignId)
			AND (@CompanyId IS NULL OR t.[CompanyId] = @CompanyId)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (ISNULL(@TaxCode, '') = '' OR t.[TaxCode] LIKE CONCAT('%', @TaxCode, '%'))
			AND (ISNULL(@Email, '') = '' OR t.[Email] LIKE CONCAT('%', @Email, '%'))
			AND (ISNULL(@Address, '') = '' OR t.[Address] LIKE CONCAT('%', @Address, '%'))
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerType' THEN r.[CustomerType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerType' THEN r.[CustomerType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'cIF' THEN r.[CIF] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'cIF' THEN r.[CIF] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'displayName' THEN r.[DisplayName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'displayName' THEN r.[DisplayName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'phoneNumber' THEN r.[PhoneNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'phoneNumber' THEN r.[PhoneNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'email' THEN r.[Email] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'email' THEN r.[Email] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'address' THEN r.[Address] END ASC,
