		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'taxCode' THEN r.[TaxCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'taxCode' THEN r.[TaxCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'firstName' THEN r.[FirstName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'firstName' THEN r.[FirstName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'lastName' THEN r.[LastName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'lastName' THEN r.[LastName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'gender' THEN r.[Gender] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'gender' THEN r.[Gender] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dateOfBirth' THEN r.[DateOfBirth] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dateOfBirth' THEN r.[DateOfBirth] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'identityNumber' THEN r.[IdentityNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'identityNumber' THEN r.[IdentityNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'identityDate' THEN r.[IdentityDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'identityDate' THEN r.[IdentityDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'identityPlace' THEN r.[IdentityPlace] END ASC,
