		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'registrationPlace' THEN r.[RegistrationPlace] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'registrationPlace' THEN r.[RegistrationPlace] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'companySize' THEN r.[CompanySize] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'companySize' THEN r.[CompanySize] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'industry' THEN r.[Industry] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'industry' THEN r.[Industry] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'legalRepresentativeName' THEN r.[LegalRepresentativeName] END ASC,
