		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'userAssignId' THEN r.[UserAssignId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'userAssignId' THEN r.[UserAssignId] END DESC,
